require_once __DIR__.'/includes/functions.php';require_role(['donor','admin']);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Listing not found.');}$q=$pdo->prepare('SELECT * FROM food_donations WHERE id=?');$q->execute([$id]);$food=$q->fetch();if(!$food||($food['donor_id']!=current_user()['id']&&current_user()['role']!=='admin')){http_response_code(404);exit('Listing not found.');}expire_donations($pdo);$q->execute([$id]);$food=$q->fetch();$errors=[];$categories=['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=$pdo->prepare('SELECT * FROM food_donations WHERE id=?');$q->execute([$id]);$food=$q->fetch();if(!in_array($food['status'],['Active','Partially Collected'],true)||strtotime($food['expiry_at'])<=time())$errors[]='Expired or closed listings cannot be edited.';$name=trim($_POST['food_name']??'');$category=$_POST['category']??'';$quantity=filter_var($_POST['quantity']??null,FILTER_VALIDATE_FLOAT);$description=trim($_POST['description']??'');$ingredients=trim($_POST['ingredients']??'');$allergens=trim($_POST['allergens']??'');$prepared=str_replace('T',' ',$_POST['prepared_at']??'');$expiry=str_replace('T',' ',$_POST['expiry_at']??'');$address=trim($_POST['pickup_address']??'');$locality=trim($_POST['locality']??'');$contact=trim($_POST['contact_number']??'');$instructions=trim($_POST['pickup_instructions']??'');if($name===''||mb_strlen($name)>150)$errors[]='Enter a food name up to 150 characters.';if(!in_array($category,$categories,true))$errors[]='Choose a valid category.';if($quantity===false||$quantity<=0)$errors[]='Enter a valid quantity.';if($description==='')$errors[]='Add a description.';if(!$prepared||strtotime($prepared)===false||strtotime($prepared)>time())$errors[]='Preparation time must be valid and in the past.';if(!$expiry||strtotime($expiry)<=time())$errors[]='Expiry time must be in the future.';if($address===''||$locality===''||$contact==='')$errors[]='Address, locality, and contact number are required.';$collected=(float)$food['quantity']-(float)$food['remaining_quantity'];$reservedQuery=$pdo->prepare("SELECT COALESCE(SUM(requested_quantity),0) FROM collection_requests WHERE donation_id=? AND status='Accepted'");$reservedQuery->execute([$id]);$reserved=(float)$reservedQuery->fetchColumn();if($quantity!==false&&$quantity<($collected+$reserved))$errors[]='Quantity cannot be less than the amount already collected and reserved for accepted pickups.';$image=$food['image'];if(!$errors){try{$uploaded=safe_upload($_FILES['image']??[]);if($uploaded)$image=$uploaded;}catch(Throwable $e){$errors[]=$e->getMessage();}}if(!$errors){$remaining=max(0,(float)$quantity-$collected);$status=$remaining<=0?'Fully Collected':($collected>0?'Partially Collected':'Active');$u=$pdo->prepare('UPDATE food_donations SET food_name=?,category=?,description=?,ingredients=?,allergens=?,quantity=?,remaining_quantity=?,prepared_at=?,expiry_at=?,pickup_address=?,locality=?,contact_number=?,image=?,pickup_instructions=?,status=? WHERE id=?');$u->execute([$name,$category,$description,$ingredients,$allergens,$quantity,$remaining,date('Y-m-d H:i:s',strtotime($prepared)),date('Y-m-d H:i:s',strtotime($expiry)),$address,$locality,$contact,$image,$instructions,$status,$id]);flash('success','Your listing has been updated.');redirect('my-donations.php');}}
